     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;Follow&nbsp;&lt;/span&gt;&lt;a class="Hyperlink SCXW259907531 BCX8" href="https://flashalert.net/id/BentonCoGov" rel="noreferrer noopener" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; text-decoration-line: none;" target="_blank"&gt;&lt;span style="color:rgb(70, 120, 134); font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;https://flashalert.net/id/BentonCoGov&lt;/span&gt;&lt;/a&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;&nbsp;for updates&nbsp;&lt;/span&gt;&lt;span style="font-family:aptos,aptos_embeddedfont,aptos_msfontservice,sans-serif; font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
